{"file_text": ".step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    gap: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 90px;
    text-align: center;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #adb5bd;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    background: #0d6efd;
    border-color: #0d6efd;
    color: #fff;
}

.step-item.completed .step-circle {
    background: #198754;
    border-color: #198754;
    color: #fff;
}

.step-item.dimmed .step-circle {
    background: #f8f9fa;
    border-color: #dee2e6;
    color: #adb5bd;
}

.step-label {
    margin-top: 4px;
    font-size: 0.78rem;
    color: #adb5bd;
    white-space: nowrap;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    min-width: 20px;
    max-width: 60px;
    margin: 0 4px;
    align-self: center;
    margin-bottom: 20px;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #198754;
}
