@page "/apply"
@rendermode InteractiveServer
@using sv_1756a7b6b03a48ebb1a58ae4523882d8.Models
@using sv_1756a7b6b03a48ebb1a58ae4523882d8.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1 class="mb-4">Job Application</h1>

<!-- Step Indicator Bar -->
<div class="step-indicator mb-4">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var state = GetStepState(stepIndex);
        <div class="step-item @state" @onclick="() => GoToStep(stepIndex)">
            <div class="step-circle">
                @if (state == "completed")
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (stepIndex < StepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < currentStep ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger">@errorMessage</div>
}

<!-- Step 1: Personal Info -->
@if (currentStep == 0)
{
    <div class="card">
        <div class="card-header"><h4 class="mb-0">Personal Information</h4></div>
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" @bind="fullName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="email" />
                @if (!string.IsNullOrEmpty(emailError))
                {
                    <div class="text-danger mt-1">@emailError</div>
                }
            </div>
            <div class="mb-3">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="phone" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <textarea class="form-control" rows="2" @bind="address"></textarea>
            </div>
            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@isProcessing">
                    @if (isProcessing) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Next
                </button>
            </div>
        </div>
    </div>
}

<!-- Step 2: Work History -->
@if (currentStep == 1)
{
    <div class="card">
        <div class="card-header"><h4 class="mb-0">Work History</h4></div>
        <div class="card-body">
            @for (int i = 0; i < workEntries.Count; i++)
