+                @if (!string.IsNullOrEmpty(emailError))
+                {
+                    <div class="text-danger mt-1">@emailError</div>
+                }
+            </div>
+            <div class="mb-3">
+                <label class="form-label">Phone <span class="text-danger">*</span></label>
+                <input type="tel" class="form-control" @bind="phone" />
+            </div>
+            <div class="mb-3">
+                <label class="form-label">Address <span class="text-danger">*</span></label>
+                <textarea class="form-control" rows="2" @bind="address"></textarea>
+            </div>
+            <div class="d-flex justify-content-end">
+                <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@isProcessing">
+                    @if (isProcessing) { <span class="spinner-border spinner-border-sm me-1"></span> }
+                    Next
+                </button>
+            </div>
+        </div>
+    </div>
+}
+
+<!-- Step 2: Work History -->
+@if (currentStep == 1)
+{
+    <div class="card">
+        <div class="card-header"><h4 class="mb-0">Work History</h4></div>
+        <div class="card-body">
+            @for (int i = 0; i < workEntries.Count; i++)
+            {
+                var idx = i;
+                <div class="border rounded p-3 mb-3 position-relative">
+                    <h5>Position @(idx + 1)</h5>
+                    @if (workEntries.Count > 1)
+                    {
+                        <button class="btn btn-sm btn-outline-danger position-absolute top-0 end-0 m-2"
+                                @onclick="() => RemoveWorkEntry(idx)">Remove</button>
+                    }
+                    <div class="row">
+                        <div class="col-md-6 mb-3">
+                            <label class="form-label">Company Name <span class="text-danger">*</span></label>
+                            <input type="text" class="form-control" @bind="workEntries[idx].Company" />
+                        </div>
+                        <div class="col-md-6 mb-3">
+                            <label class="form-label">Job Title <span class="text-danger">*</span></label>
+                            <input type="text" class="form-control" @bind="workEntries[idx].Title" />
+                        </div>
+                    </div>
+                    <div class="row">
+                        <div class="col-md-4 mb-3">
+                            <label class="form-label">Start Date <span class="text-danger">*</span></label>
+                            <input type="date" class="form-control" @bind="workEntries[idx].StartDate" />
+                        </div>
+                        <div class="col-md-4 mb-3">
+                            <label class="form-label">End Date</label>
+                            <input type="date" class="form-control" @bind="workEntries[idx].EndDate"
+                                   disabled="@workEntries[idx].IsCurrent" />
+                        </div>
+                        <div class="col-md-4 mb-3 d-flex align-items-end">
+                            <div class="form-check">
+                                <input type="checkbox" class="form-check-input" id="current-@idx"
+                                       @bind="workEntries[idx].IsCurrent" />
+                                <label class="form-check-label" for="current-@idx">Currently working here</label>
+                            </div>
+                        </div>
+                    </div>
+                    <div class="mb-3">
+                        <label class="form-label">Description</label>
+                        <textarea class="form-control" rows="3" @bind="workEntries[idx].Description"></textarea>
+                    </div>
+                </div>
+            }
+            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">
+                + Add Another Position
+            </button>
+            <div class="d-flex justify-content-between">
+                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
+            </div>
+        </div>
+    </div>
+}
+
+<!-- Step 3: References -->
+@if (currentStep == 2)
+{
+    <div class="card">
+        <div class="card-header"><h4 class="mb-0">References</h4></div>
+        <div class="card-body">
+            @for (int i = 0; i < references.Count; i++)
+            {
+                var idx = i;
+                <div class="border rounded p-3 mb-3 position-relative">
+                    <h5>Reference @(idx + 1)</h5>
+                    @if (references.Count > 2)
+                    {
+                        <button class="btn btn-sm btn-outline-danger position-absolute top-0 end-0 m-2"
+                                @onclick="() => RemoveReference(idx)">Remove</button>
+                    }
+                    <div class="row">
+                        <div class="col-md-6 mb-3">
+                            <label class="form-label">Name <span class="text-danger">*</span></label>
+                            <input type="text" class="form-control" @bind="references[idx].Name" />
+                        </div>
+                        <div class="col-md-6 mb-3">
+                            <label class="form-label">Relationship <span class="text-danger">*</span></label>
+                            <input type="text" class="form-control" @bind="references[idx].Relationship" />
+                        </div>
+                    </div>
+                    <div class="row">
+                        <div class="col-md-6 mb-3">
+                            <label class="form-label">Email <span class="text-danger">*</span></label>
+                            <input type="email" class="form-control" @bind="references[idx].Email" />
+                        </div>
+                        <div class="col-md-6 mb-3">
+                            <label class="form-label">Phone <span class="text-danger">*</span></label>
+                            <input type="tel" class="form-control" @bind="references[idx].Phone" />
+                        </div>
+                    </div>
+                </div>
+            }
+            @if (references.Count < 3)
+            {
+                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
+                    + Add Reference
+                </button>
+            }
+            <div class="d-flex justify-content-between">
+                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
+            </div>
+        </div>
+    </div>
+}
+
+<!-- Step 4: Cover Letter -->
+@if (currentStep == 3)
+{
+    <div class="card">
+        <div class="card-header"><h4 class="mb-0">Cover Letter</h4></div>
+        <div class="card-body">
+            <div class="mb-2">
+                <textarea class="form-control" rows="12" maxlength="2000"
+                          @bind="coverLetter" @bind:event="oninput"></textarea>
+            </div>
+            <div class="text-muted mb-3">@(coverLetter?.Length ?? 0) / 2000 characters</div>
+            <div class="d-flex justify-content-between">
+                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
+            </div>
+        </div>
+    </div>
+}
+
+<!-- Step 5: Review & Submit -->
+@if (currentStep == 4)
+{
+    @if (isSubmitted)
+    {
+        <div class="card border-success">
+            <div class="card-body text-center py-5">
+                <div class="text-success mb-3" style="font-size: 3rem;">✓</div>
+                <h3 class="text-success">Application Submitted!</h3>
+                <p class="lead">Your application ID is <strong>#@submittedId</strong></p>
+                <p class="text-muted">Thank you for applying. We will review your application and get back to you.</p>
+            </div>
+        </div>
+    }
+    else
+    {
+        <div class="card">
+            <div class="card-header"><h4 class="mb-0">Review & Submit</h4></div>
+            <div class="card-body">
+                <!-- Personal Info Summary -->
+                <div class="mb-4">
+                    <div class="d-flex justify-content-between align-items-center">
+                        <h5>Personal Information</h5>
+                        <button class="btn btn-sm btn-link" @onclick="() => GoToStep(0)">Edit</button>
+                    </div>
+                    <dl class="row mb-0">
+                        <dt class="col-sm-3">Full Name</dt>
+                        <dd class="col-sm-9">@fullName</dd>
+                        <dt class="col-sm-3">Email</dt>
+                        <dd class="col-sm-9">@email</dd>
+                        <dt class="col-sm-3">Phone</dt>
+                        <dd class="col-sm-9">@phone</dd>
+                        <dt class="col-sm-3">Address</dt>
+                        <dd class="col-sm-9">@address</dd>
+                    </dl>
+                </div>
+                <hr />
+
+                <!-- Work History Summary -->
+                <div class="mb-4">
+                    <div class="d-flex justify-content-between align-items-center">
+                        <h5>Work History</h5>
+                        <button class="btn btn-sm btn-link" @onclick="() => GoToStep(1)">Edit</button>
+                    </div>
+                    @foreach (var entry in workEntries)
+                    {
+                        <div class="border-start border-3 ps-3 mb-3">
+                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
+                            <small class="text-muted">
+                                @entry.StartDate.ToString("MMM yyyy") —
+                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
+                            </small>
+                            @if (!string.IsNullOrWhiteSpace(entry.Description))
+                            {
+                                <p class="mt-1 mb-0">@entry.Description</p>
+                            }
+                        </div>
+                    }
+                </div>
+                <hr />
+
+                <!-- References Summary -->
+                <div class="mb-4">
+                    <div class="d-flex justify-content-between align-items-center">
+                        <h5>References</h5>
+                        <button class="btn btn-sm btn-link" @onclick="() => GoToStep(2)">Edit</button>
+                    </div>
+                    @foreach (var r in references)
+                    {
+                        <div class="mb-2">
+                            <strong>@r.Name</strong> (@r.Relationship)<br />
+                            <small class="text-muted">@r.Email · @r.Phone</small>
+                        </div>
+                    }
+                </div>
+                <hr />
+
+                <!-- Cover Letter Summary -->
+                <div class="mb-4">
+                    <div class="d-flex justify-content-between align-items-center">
+                        <h5>Cover Letter</h5>
+                        <button class="btn btn-sm btn-link" @onclick="() => GoToStep(3)">Edit</button>
+                    </div>
+                    <div class="bg-light p-3 rounded" style="white-space: pre-wrap;">@coverLetter</div>
+                </div>
+
+                <div class="d-flex justify-content-between">
+                    <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+                    <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@isProcessing">
+                        @if (isProcessing) { <span class="spinner-border spinner-border-sm me-1"></span> }
+                        Submit Application
+                    </button>
+                </div>
+            </div>
+        </div>
+    }
+}
+
+@code {
+    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+
+    private int currentStep;
+    private int highestCompletedStep = -1;
+    private string? errorMessage;
+    private bool isProcessing;
+    private bool isSubmitted;
+    private int submittedId;
+
+    // Step 1
+    private string fullName = "";
+    private string email = "";
+    private string phone = "";
+    private string address = "";
+    private string? emailError;
+
+    // Step 2
+    private List<WorkEntryModel> workEntries = new() { new() };
+
+    // Step 3
+    private List<ReferenceModel> references = new() { new(), new() };
+
+    // Step 4
+    private string coverLetter = "";
+
+    private string GetStepState(int step)
+    {
+        if (step == currentStep) return "active";
+        if (step <= highestCompletedStep) return "completed";
+        return "dimmed";
+    }
+
+    private void GoToStep(int step)
+    {
+        if (step <= highestCompletedStep || step == currentStep)
+        {
+            errorMessage = null;
+            emailError = null;
+            currentStep = step;
+        }
+    }
+
+    private void PreviousStep()
+    {
+        errorMessage = null;
+        emailError = null;
+        currentStep--;
+    }
+
+    private void AdvanceStep()
+    {
+        if (currentStep > highestCompletedStep)
+            highestCompletedStep = currentStep;
+        currentStep++;
+        errorMessage = null;
+    }
+
+    // Step 1 validation
+    private async Task NextFromPersonalInfo()
+    {
+        emailError = null;
+        errorMessage = null;
+
+        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email)
+            || string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
+        {
+            errorMessage = "Please fill in all required fields.";
+            return;
+        }
+
+        isProcessing = true;
+        try
+        {
+            var valid = await ApplicationService.ValidateEmailAsync(email);
+            if (!valid)
+            {
+                emailError = "Please enter a valid email address.";
+                isProcessing = false;
+                return;
+            }
+        }
+        finally
+        {
+            isProcessing = false;
+        }
+
+        AdvanceStep();
+    }
+
+    // Step 2 validation
+    private void NextFromWorkHistory()
+    {
+        errorMessage = null;
+        foreach (var entry in workEntries)
+        {
+            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
+                || entry.StartDate == default)
+            {
+                errorMessage = "Please fill in the company name, job title, and start date for each position.";
+                return;
+            }
+        }
+        AdvanceStep();
+    }
+
+    // Step 3 validation
+    private void NextFromReferences()
+    {
+        errorMessage = null;
+        foreach (var r in references)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
+                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
+            {
+                errorMessage = "Please fill in all fields for each reference.";
+                return;
+            }
+        }
+        AdvanceStep();
+    }
+
+    // Step 4
+    private void NextFromCoverLetter()
+    {
+        errorMessage = null;
+        if (string.IsNullOrWhiteSpace(coverLetter))
+        {
+            errorMessage = "Please write a cover letter.";
+            return;
+        }
+        AdvanceStep();
+    }
+
+    // Step 2 helpers
+    private void AddWorkEntry() => workEntries.Add(new WorkEntryModel());
+    private void RemoveWorkEntry(int index) { if (workEntries.Count > 1) workEntries.RemoveAt(index); }
+
+    // Step 3 helpers
+    private void AddReference() { if (references.Count < 3) references.Add(new ReferenceModel()); }
+    private void RemoveReference(int index) { if (references.Count > 2) references.RemoveAt(index); }
+
+    // Submit
+    private async Task SubmitApplication()
+    {
+        isProcessing = true;
+        errorMessage = null;
+        try
+        {
+            var personal = new PersonalInfo(fullName, email, phone, address);
+            var work = new WorkHistory(workEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? "")
+            ).ToList());
+            var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+            var application = new JobApplication(personal, work, refs, coverLetter);
+
+            submittedId = await ApplicationService.SubmitApplicationAsync(application);
+            isSubmitted = true;
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            isProcessing = false;
+        }
+    }
+
+    // Mutable models for form binding
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = "";
+        public string Title { get; set; } = "";
+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string? Description { get; set; } = "";
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = "";
+        public string Relationship { get; set; } = "";
+        public string Email { get; set; } = "";
+        public string Phone { get; set; } = "";
+    }
+}
+

toolArgs.file_text:
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    gap: 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 90px;
    text-align: center;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #adb5bd;
    transition: all 0.2s;
}

.step-item.active .step-circle {
    background: #0d6efd;
    border-color: #0d6efd;
    color: #fff;
}

.step-item.completed .step-circle {
    background: #198754;
    border-color: #198754;
    color: #fff;
}

.step-item.dimmed .step-circle {
    background: #f8f9fa;
    border-color: #dee2e6;
    color: #adb5bd;
}

.step-label {
    margin-top: 4px;
    font-size: 0.78rem;
    color: #adb5bd;
    white-space: nowrap;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    min-width: 20px;
    max-width: 60px;
    margin: 0 4px;
    align-self: center;
    margin-bottom: 20px;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #198754;
}

